 collecting\n  open_metric = true\n\n  # Extra tags\n  [inputs.host_processes.tags]\n  # some_tag = \"some_value\"\n  # more_tag = \"some_other_value\"\n  # ...\n','',0,'2025-06-03 15:16:17','2025-06-03 15:16:17','2025-06-03 15:16:16','2025-06-03 15:16:17','',''),(43,'8473a95c-c58c-40af-8bcf-79f1bc3f82f0','3ea173f7-9f97-4019-9703-e950f17c53d0','',0,'','2025-06-03 15:16:48','2025-06-03 15:16:49','S',30,'Success','bo:runShellScript','{\"documentType\":\"SendCommand\",\"documentInfo\":{\"instanceId\":\"8473a95c-c58c-40af-8bcf-79f1bc3f82f0\",\"messageId\":\"3ea173f7-9f97-4019-9703-e950f17c53d0\",\"createdDate\":\"2025-06-03 15:16:48\"},\"pluginInfo\":{\"properties\":{\"cmd\":\"#!/bin/bash\\n\\ncat /usr/local/stplugins/st_datasleuth/default/bin/conf.d/prom/prom-keepalived.conf\",\"runAsUser\":\"\",\"userPwd\":\"\",\"workingDir\":\"/usr/local/stplugins/st_datasleuth/default/bin\",\"timeoutSeconds\":30,\"environment\":null,\"scriptType\":1},\"pluginName\":\"bo:runShellScript\",\"messageId\":\"3ea173f7-9f97-4019-9703-e950f17c53d0\"}}\n','','# {\"version\": \"not-set\", \"desc\": \"do NOT edit this line\"}\n\n[[inputs.prom]]\n  # 是否启用该input\n  enable_input = false\n\n  # Exporter URLs.\n  urls = [\"http://127.0.0.1:9165/metrics\"]\n\n  # Unix Domain Socket URL. Using socket to request data when not empty.\n  uds_path = \"\"\n\n  # Ignore URL request errors.\n  ignore_req_err = false\n\n  ## Collector alias.\n  source = \"\"\n\n  ## Collect data output.\n  # Fill this when want to collect the data to local file nor center.\n  # After filling, could use \'datakit --prom-conf /path/to/this/conf\' to debug local storage measurement set.\n  # Using \'--prom-conf\' when priority debugging data in \'output\' path.\n  # output = \"/abs/path/to/file\"\n\n  ## Collect data upper limit as bytes.\n  # Only available when set output to local file.\n  # If collect data exceeded the limit, the data would be dropped.\n  # Default is 32MB.\n  # max_file_size = 0\n\n  ## Metrics type whitelist. Optional: counter, gauge, histogram, summary\n  # Default only collect \'counter\' and \'gauge\'.\n  # Collect all if empty.\n  metric_types = []\n\n  ## Metrics name whitelist.\n  # Regex supported. Multi supported, conditions met when one matched.\n  # Collect all if empty.\n  # metric_name_filter = [\"cpu\"]\n\n  ## Measurement prefix.\n  # Add prefix to measurement set name.\n  measurement_prefix = \"keepalived_\"\n  interval = \"60s\"\n  ## Measurement name.\n  # If measurement_name is empty, split metric name by \'_\', the first field after split as measurement set name, the rest as current metric name.\n  # If measurement_name is not empty, using this as measurement set name.\n  # Always add \'measurement_prefix\' prefix at last.\n  # measurement_name = \"prom\"\n\n  ## TLS configuration.\n  tls_open = false\n  # tls_ca = \"/tmp/ca.crt\"\n  # tls_cert = \"/tmp/peer.crt\"\n  # tls_key = \"/tmp/peer.key\"\n\n  ## Set to \'true\' to enable election.\n  election = false\n\n  # disable setting host tag for this input\n  disable_host_tag = false\n\n  # disable setting instance tag for this input\n  disable_instance_tag = false\n\n  # Ignore tags. Multi supported.\n  # The matched tags would be dropped, but the item would still be sent.\n  # tags_ignore = [\"xxxx\"]\n\n  ## Customize authentification. For now support Bearer Token only.\n  # Filling in \'token\' or \'token_file\' is acceptable.\n  # [inputs.prom.auth]\n  # type = \"bearer_token\"\n  # token = \"xxxxxxxx\"\n  # token_file = \"/tmp/token\"\n\n  ## Customize measurement set name.\n  # Treat those metrics with prefix as one set.\n  # Prioritier over \'measurement_name\' configuration.\n  #[[inputs.prom.measurements]]\n  #  prefix = \"cpu_\"\n  #  name = \"cpu\"\n\n  # [[inputs.prom.measurements]]\n  # prefix = \"mem_\"\n  # name = \"mem\"\n\n  # Not collecting those data when tag matched.\n  [inputs.prom.ignore_tag_kv_match]\n  # key1 = [ \"val1.*\", \"val2.*\"]\n  # key2 = [ \"val1.*\", \"val2.*\"]\n\n  # Add HTTP headers to data pulling.\n  [inputs.prom.http_headers]\n  # Root = \"passwd\"\n  # Michael = \"1234\"\n\n  # Rename tag key in prom data.\n  [inputs.prom.tags_rename]\n    overwrite_exist_tags = false\n    [inputs.prom.tags_rename.mapping]\n    # tag1 = \"new-name-1\"\n    # tag2 = \"new-name-2\"\n    # tag3 = \"new-name-3\"\n\n  # Send collected metrics to center as log.\n  # When \'service\' field is empty, using \'service tag\' as measurement set name.\n  [inputs.prom.as_logging]\n    enable = false\n    service = \"service_name\"\n\n  ## Customize tags.\n  [inputs.prom.tags]\n  # some_tag = \"some_value\"\n  # more_tag = \"some_other_value\"\n','','# {\"version\": \"not-set\", \"desc\": \"do NOT edit this line\"}\n\n[[inputs.prom]]\n  # 是否启用该input\n  enable_input = false\n\n  # Exporter URLs.\n  urls = [\"http://127.0.0.1:9165/metrics\"]\n\n  # Unix Domain Socket URL. Using socket to request data when not empty.\n  uds_path = \"\"\n\n  # Ignore URL request errors.\n  ignore_req_err = false\n\n  ## Collector alias.\n  source = \"\"\n\n  ## Collect data output.\n  # Fill this when want to collect the data to local file nor center.\n  # After filling, could use \'datakit --prom-conf /path/to/this/conf\' to debug local storage measurement set.\n  # Using \'--prom-conf\' when priority debugging data in \'output\' path.\n  # output = \"/abs/path/to/file\"\n\n  ## Collect data upper limit as bytes.\n  # Only available when set output to local file.\n  # If collect data exceeded the limit, the data would be dropped.\n  # Default is 32MB.\n  # max_file_size = 0\n\n  ## Metrics type whitelist. Optional: counter, gauge, histogram, summary\n  # Default only collect \'counter\' and \'gauge\'.\n  # Collect all if empty.\n  metric_types = []\n\n  ## Metrics name whitelist.\n  # Regex supported. Multi supported, conditions met when one matched.\n  # Collect all if empty.\n  # metric_name_filter = [\"cpu\"]\n\n  ## Measurement prefix.\n  # Add prefix to measuremen