ype other than list, set, hash, or sorted set.\n  #\n  # keys = [\"KEY_1\", \"KEY_PATTERN\"]\n  \n  ## @param warn_on_missing_keys - boolean - optional - default: true\n  ## If you provide a list of \'keys\', set this to true to have the Agent log a warning\n  ## when keys are missing.\n  #\n  # warn_on_missing_keys = true\n  \n  ## @param slow_log - boolean - optional - default: true\n  slow_log = true\n  \n  ## @param all_slow_log - boolean - optional - default: false\n  ## Collect all slowlogs returned by Redis. When set to false, will only collect slowlog \n  ## that are generated after this input starts, and collect the same slowlog only once.\n  all_slow_log = false\n\n  ## @param slowlog-max-len - integer - optional - default: 128\n  slowlog-max-len = 128\n  \n  ## @param command_stats - boolean - optional - default: false\n  ## Collect INFO COMMANDSTATS output as metrics.\n  # command_stats = false\n\n  ## Set true to enable election\n  election = true\n  \n  # [inputs.redis.log]\n  # #required, glob logfiles\n  # files = [\"/var/log/redis/*.log\"]\n  \n  ## glob filteer\n  #ignore = [\"\"]\n  \n  ## grok pipeline script path\n  #pipeline = \"redis.p\"\n  \n  ## optional encodings:\n  ##    \"utf-8\", \"utf-16le\", \"utf-16le\", \"gbk\", \"gb18030\" or \"\"\n  #character_encoding = \"\"\n  \n  ## The pattern should be a regexp. Note the use of \'\'\'this regexp\'\'\'\n  ## regexp link: https://golang.org/pkg/regexp/syntax/#hdr-Syntax\n  #match = \'\'\'^\\S.*\'\'\'\n  \n  [inputs.redis.tags]\n  # some_tag = \"some_value\"\n  # more_tag = \"some_other_value\"\n','',0,'2025-06-03 15:23:55','2025-06-03 15:23:56','2025-06-03 15:23:55','2025-06-03 15:23:56','',''),(57,'8473a95c-c58c-40af-8bcf-79f1bc3f82f0','1cca99dd-5af1-41fb-9af8-cc04f5674a11','',0,'','2025-06-03 15:24:01','2025-06-03 15:24:02','S',30,'Success','bo:runShellScript','{\"documentType\":\"SendCommand\",\"documentInfo\":{\"instanceId\":\"8473a95c-c58c-40af-8bcf-79f1bc3f82f0\",\"messageId\":\"1cca99dd-5af1-41fb-9af8-cc04f5674a11\",\"createdDate\":\"2025-06-03 15:24:01\"},\"pluginInfo\":{\"properties\":{\"cmd\":\"#!/bin/bash\\n\\ncat /usr/local/stplugins/st_datasleuth/default/bin/conf.d/prom/prom-doris.conf\",\"runAsUser\":\"\",\"userPwd\":\"\",\"workingDir\":\"/usr/local/stplugins/st_datasleuth/default/bin\",\"timeoutSeconds\":30,\"environment\":null,\"scriptType\":1},\"pluginName\":\"bo:runShellScript\",\"messageId\":\"1cca99dd-5af1-41fb-9af8-cc04f5674a11\"}}\n','','# {\"version\": \"not-set\", \"desc\": \"do NOT edit this line\"}\n\n[[inputs.prom]]\n  # 是否启用该input\n  enable_input = false\n\n  # Exporter URLs.\n  # doris的指标数据分为fe和be，此处分别填写http://fe_host:http_port/metrics，http://be_host:webserver_port/metrics\n  # 集群的每台机器都分别采集\n  urls = [\"http://127.0.0.1:8030/metrics\",\"http://127.0.0.1:8040/metrics\"]\n\n  # Unix Domain Socket URL. Using socket to request data when not empty.\n  uds_path = \"\"\n\n  # 采集间隔 \"ns\", \"us\" (or \"µs\"), \"ms\", \"s\", \"m\", \"h\"\n  interval = \"1m\"\n  # Ignore URL request errors.\n  ignore_req_err = false\n\n  ## Collector alias.\n  source = \"doris\"\n\n  ## Collect data output.\n  # Fill this when want to collect the data to local file nor center.\n  # After filling, could use \'datakit --prom-conf /path/to/this/conf\' to debug local storage measurement set.\n  # Using \'--prom-conf\' when priority debugging data in \'output\' path.\n  # output = \"/abs/path/to/file\"\n\n  ## Collect data upper limit as bytes.\n  # Only available when set output to local file.\n  # If collect data exceeded the limit, the data would be dropped.\n  # Default is 32MB.\n  # max_file_size = 0\n\n  ## Metrics type whitelist. Optional: counter, gauge, histogram, summary\n  # Default only collect \'counter\' and \'gauge\'.\n  # Collect all if empty.\n  metric_types = [\"counter\", \"gauge\"]\n\n  ## Metrics name whitelist.\n  # Regex supported. Multi supported, conditions met when one matched.\n  # Collect all if empty.\n  # metric_name_filter = [\"cpu\"]\n\n  ## Measurement prefix.\n  # Add prefix to measurement set name.\n  measurement_prefix = \"\"\n\n  ## Measurement name.\n  # If measurement_name is empty, split metric name by \'_\', the first field after split as measurement set name, the rest as current metric name.\n  # If measurement_name is not empty, using this as measurement set name.\n  # Always add \'measurement_prefix\' prefix at last.\n  measurement_name = \"doris\"\n\n  ## TLS configuration.\n  tls_open = false\n  # tls_ca = \"/tmp/ca.crt\"\n  # tls_cert = \"/tmp/peer.crt\"\n  # tls_key = \"/tmp/peer.key\"\n\n  ## Set to \'true\' to enable election.\n  election = true\n\n  # disable setting host tag for this input\n  disable_host_tag = false\n\n  # disable setting instance tag for this input\n  disable_instance_tag = false\n\n  # Ignore tags. Multi supported.\n  # The matched tags would be dropped, but the item would still be sent.\n  # tags_ignore = [\"xxxx\"]\n\n  ## Customize authentification. For now support Bearer Token only.\n  # Filling in \'token\' or \'token_file\' is acceptable.\n  # [inputs.prom.auth]\n  # type = \"bearer_token\"\n  # token = \"xxxxxxxx\"\n  # token_file = \"/tmp/token\"\n\n  ## Customize measurement set name.\n  # Treat those metrics with prefix as one set.\n  # Prioritier over \'measurement_name\' configuration.\n\n  [[inputs.prom.measurements]]\n    prefix = \"doris_\"\n    name = \"doris\"\n\n  # Not collecting those data when tag matched.\n  [inputs.prom.ignore_tag_kv_match]\n  # key1 = [ \"val1.*\", \"val2.*\"]\n  # key2 = [ \"val1.*\", \"val2.*\"]\n\n  # Add HTTP headers to data pulling.\n  [inputs.prom.http_headers]\n  # Root = \"passwd\"\n  # Michael = \"1234\"\n\n  # Rename tag key in prom data.\n  [inputs.prom.tags_rename]\n    overwrite_exist_tags = false\n    [inputs.prom.tags_rename.mapping]\n    # tag1 = \"new-name-1\"\n    # tag2 = \"new-name-2\"\n    # tag3 = \"new-name-3\"\n\n  # Send collected metrics to center as log.\n  # When \'service\' field is empty, using \'service tag\' as measurement set name.\n  [inputs.prom.as_logging]\n    enable = false\n    service = \"service_name\"\n\n  ## Customize tags.\n  [inputs.prom.tags]\n  # some_tag = \"some_value\"\n  # more_tag = \"some_other_value\"\n  cluster_name = \"metric_cluster_name\"','','# {\"version\": \"not-set\", \"desc\": \"do NOT edit this line\"}\n\n[[inputs.prom]]\n  # 是否启用该input\n  enable_input = false\n\n  # Exporter URLs.\n  # doris的指标数据分为fe和be，此处分别填写http://fe_host:http_port/metrics，http://be_host:webserver_port/metrics\n  # 集群的每台机器都分别采集\n  urls = [\"http://127.0.0.1:8030/metrics\",\"http://127.0.0.1:8040/metrics\"]\n\n  # Unix Domain Socket URL. Using socket to request data when not empty.\n  uds_path = \"\"\n\n  # 采集间隔 \"ns\", \"us\" (or \"µs\"), \"ms\", \"s\", \"m\", \"h\"\n  interval = \"1m\"\n  # Ignore URL request errors.\n  ignore_req_err = false\n\n  ## Collector alias.\n  source = \"doris\"\n\n  ## Collect data output.\n  # Fill this when want to collect the data to local file nor center.\n  # After filling, could use \'datakit --prom-conf /path/to/this/conf\' to debug local storage measurement set.\n  # Using \'--prom-conf\' when priority debugging data in \'output\' path.\n  # output = \"/abs/path/to/file\"\n\n  ## Collect data upper limit as bytes.\n  # Only available when set output to local file.\n  # If collect data exceeded the limit, the data would be dropped.\n  # Default is 32MB.\n  # max_file_size = 0\n\n  ## Metrics type whitelist. Optional: counter, gauge, histogram, summary\n  # Default only collect \'counter\' and \'gauge\'.\n  # Collect all if empty.\n  metric_types = [\"counter\", \"gauge\"]\n\n  ## Metrics name whitelist.\n  # Regex supported. Multi supported, conditions met when one matched.\n  # Collect all if empty.\n  # metric_name_filter = [\"cpu\"]\n\n  ## Measurement prefix.\n  # Add prefix to measurement set name.\n  measurement_prefix = \"\"\n\n  ## Measurement name.\n  # If measurement_name is empty, split met