DROP TABLE IF EXISTS `bo_file_dispense`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `bo_file_dispense` (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT,
  `IDENTIFY` varchar(64) DEFAULT NULL COMMENT '标识',
  `FROM` varchar(64) DEFAULT NULL COMMENT '发送方',
  `FROM_PATH` varchar(250) DEFAULT NULL COMMENT '发送文件路径',
  `UPLOAD_LIMIT` int(11) DEFAULT NULL COMMENT '上传限速',
  `DOWNLOAD_LIMIT` int(11) DEFAULT NULL COMMENT '下载限速',
  `CREATE_TIME` datetime DEFAULT NULL,
  `UPDATE_TIME` datetime DEFAULT NULL,
  `CALLBACK_URL` varchar(250) DEFAULT NULL,
  `TIMEOUT_SECONDS` int(11) DEFAULT NULL COMMENT '超时时间',
  `KIND` int(11) DEFAULT NULL COMMENT '分发类型，默认0带中转  1带中转同时带proxy优化',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

