--
-- Table structure for table `bo_job_result_item`
--

DROP TABLE IF EXISTS `bo_job_result_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `bo_job_result_item` (
  `ID` varchar(255) NOT NULL COMMENT '主键',
  `JOB_RESULT_ID` varchar(255) DEFAULT NULL COMMENT '执行历史ID',
  `INSTANCE_ID` varchar(255) DEFAULT NULL COMMENT '实例ID',
  `IP` varchar(255) DEFAULT NULL COMMENT '实例IP',
  `SCRIPT_TYPE` varchar(255) DEFAULT NULL COMMENT '脚本类型',
  `SCRIPT_CONTENT` text COMMENT '脚本内容',
  `ENV_VARS` varchar(500) DEFAULT NULL COMMENT '环境变量',
  `EXEC_USER` varchar(255) DEFAULT NULL COMMENT '执行用户',
  `EXEC_TIMEOUT` bigint(20) DEFAULT NULL COMMENT '超时时间',
  `STATUS` tinyint(1) DEFAULT NULL COMMENT '状态，0:成功 1:失败 2:超时 3:等待',
  `START_TIME` datetime DEFAULT NULL COMMENT '开始时间',
  `END_TIME` datetime DEFAULT NULL COMMENT '结束时间',
  `EXECUTE_TIME` varchar(255) DEFAULT NULL COMMENT '执行时间',
  `LOG` text COMMENT '执行日志',
  `WORKSPACE_ID` varchar(64) DEFAULT NULL COMMENT '工作空间ID',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `CREATE_USER` varchar(36) DEFAULT NULL COMMENT '创建用户',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '更新时间',
  `UPDATE_USER` varchar(36) DEFAULT NULL COMMENT '更新用户',
  PRIMARY KEY (`ID`),
  KEY `IDX_BO_JOB_RESULT_ITEM_JOB_RESULT_ID` (`JOB_RESULT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

