CREATE TABLE `bo_job_script` (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `NAME` varchar(300) NOT NULL COMMENT '脚本名称',
  `TYPE` varchar(255) NOT NULL COMMENT '脚本类型',
  `CONTENT` text NOT NULL COMMENT '脚本内容',
  `DESCRIPTION` text COMMENT '备注',
  `WORKSPACE_ID` varchar(64) DEFAULT NULL COMMENT '工作空间ID',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `CREATE_USER` varchar(36) DEFAULT NULL COMMENT '创建用户',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '更新时间',
  `UPDATE_USER` varchar(36) DEFAULT NULL COMMENT '更新用户',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8;
