  `TYPE` tinyint(1) NOT NULL COMMENT '任务类型: 0 定时',
  `TAGS` varchar(512) DEFAULT NULL COMMENT '标签',
  `SCRIPT_ID` bigint(20) NOT NULL COMMENT '脚本id',
