  `INTERVAL` varchar(10) DEFAULT NULL COMMENT '执行间隔',
  `CRON` varchar(100) DEFAULT NULL COMMENT 'cron表达式',
  `EXEC_USER` varchar(32) DEFAULT NULL COMMENT '执行用户',
  `EXEC_TIMEOUT` tinyint(3) NOT NULL COMMENT '执行超时时间(单位:秒)',
  `WORKSPACE_ID` varchar(64) DEFAULT NULL COMMENT '工作空间ID',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `CREATE_USER` varchar(36) DEFAULT NULL COMMENT '创建用户',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '更新时间',
  `UPDATE_USER` varchar(36) DEFAULT NULL COMMENT '更新用户',
  PRIMARY KEY (`ID`)
