--
-- Table structure for table `bo_node`
--

DROP TABLE IF EXISTS `bo_node`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `bo_node` (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `ACCESS_POINT_ID` bigint(20) DEFAULT NULL COMMENT '接入点ID',
  `INSTANCE_ID` varchar(36) DEFAULT NULL COMMENT '实例ID',
  `TAG` varchar(50) DEFAULT NULL COMMENT '节点标签',
  `REGISTER_ID` bigint(20) DEFAULT NULL COMMENT '注册用户ID',
  `MACHINE_ID` varchar(100) DEFAULT NULL COMMENT '机器码',
  `NODE_TYPE` varchar(10) DEFAULT 'AGENT' COMMENT '节点类型，AGENT或PROXY',
  `HOSTNAME` varchar(200) DEFAULT NULL COMMENT '主机名',
  `INTRANET_IP` varchar(20) DEFAULT NULL COMMENT 'IP',
  `OUTER_IP` varchar(20) DEFAULT NULL COMMENT '外网IP',
  `OS_VERSION` varchar(100) DEFAULT NULL COMMENT '系统版本',
  `OS_TYPE` varchar(20) DEFAULT NULL COMMENT '系统类型',
  `OS_ARCH` varchar(20) DEFAULT NULL COMMENT '系统arch',
  `CLIENT_VERSION` varchar(50) DEFAULT NULL COMMENT '客户端版本',
  `PUBLIC_KEY_BASE64` varchar(512) DEFAULT NULL COMMENT '公钥',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '更新时间',
  `JOB_ID` bigint(20) DEFAULT NULL COMMENT '最后执行的job id',
  `SELF_UPDATE` int(11) DEFAULT '1' COMMENT '是否自更新',
  `DEL_FLAG` int(11) DEFAULT '0',
  `LAST_INSTALL` datetime DEFAULT NULL COMMENT '最后安装时间',
  `LAST_REPORT` datetime DEFAULT NULL COMMENT '最后心跳时间',
  `INSTALL_TYPE` int(11) DEFAULT '1' COMMENT '安装方式，0代表远程安装，1代表手动安装',
  `APP_ID` bigint(20) DEFAULT NULL COMMENT '所属业务id',
  `ENDPOINT` varchar(200) DEFAULT NULL COMMENT '实际接入ip',
  `PROGRAM_PATH` varchar(120) DEFAULT NULL COMMENT '程序所在目录',
  `TRANSFER_IOPS_ID` bigint(20) NOT NULL DEFAULT '0' COMMENT '移交方id',
  `TRANSFER_TASK_ID` bigint(20) NOT NULL DEFAULT '0' COMMENT '移交任务id',
  `DATA_GROUP` varchar(64) DEFAULT NULL COMMENT '数据单元',
  `WORK_SPACE_ID` varchar(32) DEFAULT NULL COMMENT '工作空间',
  `USERNAME` varchar(32) DEFAULT NULL COMMENT '安装用户名',
  PRIMARY KEY (`ID`),
  UNIQUE KEY `UQE_BO_NODE_INSTANCE_ID` (`INSTANCE_ID`),
  KEY `IDX_BO_NODE_ACCESS_POINT_ID` (`ACCESS_POINT_ID`),
  KEY `IDX_BO_NODE_REGISTER_ID` (`REGISTER_ID`),
  KEY `IDX_BO_NODE_INTRANET_IP` (`INTRANET_IP`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

