--
-- Table structure for table `bo_node_deploy_task`
--

DROP TABLE IF EXISTS `bo_node_deploy_task`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `bo_node_deploy_task` (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `INSTANCE` varchar(50) DEFAULT NULL COMMENT '关联实体',
  `NODE_INDEX` varchar(50) DEFAULT NULL COMMENT '关联节点',
  `UNI_CODE` varchar(64) DEFAULT NULL COMMENT '唯一标示',
  `CREATED_BY` varchar(50) DEFAULT NULL COMMENT '创建人',
  `START_TIME` datetime DEFAULT NULL COMMENT '开始时间',
  `END_TIME` datetime DEFAULT NULL COMMENT '结束时间',
  `BIZ_ID` bigint(20) DEFAULT NULL COMMENT '所属业务id',
  `TASK_TYPE` int(11) DEFAULT NULL COMMENT '任务类型',
  `OPT_TYPE` int(11) DEFAULT NULL COMMENT '操作方式',
  `STATUS` char(1) DEFAULT NULL COMMENT '状态',
  `CMD` varchar(1024) DEFAULT NULL COMMENT '安装命令',
  `STATUS_DISPLAY` varchar(500) DEFAULT NULL COMMENT '失败详细描述',
  `PAYLOAD` text COMMENT '任务附加数据',
  `IP` varchar(64) DEFAULT NULL,
  `LOG` text COMMENT '任务日志',
  `WORK_SPACE_ID` varchar(32) DEFAULT NULL COMMENT '工作空间',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '更新时间',
  `CHECK_STATUS` int(11) DEFAULT NULL COMMENT '检查状态，默认0为未处理',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB AUTO_INCREMENT=55 DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

