CREATE TABLE `bo_workflow` (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT,
  `SEQUENCE` varchar(64) DEFAULT NULL COMMENT '流程序号',
  `JOB_NAME` varchar(30) DEFAULT NULL COMMENT '流程名称',
  `JOB_TYPE` varchar(30) DEFAULT NULL,
  `JOB_SEQUENCE` varchar(64) DEFAULT NULL COMMENT '流程关联外键编号',
  `INSTANCE` varchar(50) DEFAULT NULL COMMENT '关联实体',
  `NAME` varchar(30) DEFAULT NULL COMMENT '流程分部名称',
  `PARAM` text COMMENT '流程分部参数',
  `STATUS` varchar(12) DEFAULT NULL COMMENT '流程分部状态',
  `LOG` text COMMENT '流程分部日志',
  `CREATED_BY` varchar(50) DEFAULT NULL COMMENT '创建人',
  `CREATE_TIME` datetime DEFAULT NULL,
  `UPDATE_TIME` datetime DEFAULT NULL,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB AUTO_INCREMENT=79 DEFAULT CHARSET=utf8;
